use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input["jobs"].as_array().unwrap();
    let quantum = input["quantum"].as_u64().unwrap();
    let mut indices = Vec::new();

    for (index, job) in jobs.iter().enumerate() {
        if job.is_u64() {
            indices.push(index);
        }
    }

    indices.sort_unstable_by(|a, b| {
        let a_value = indices[a];
        let b_value = indices[b];
        if a_value == b_value {
            return a.cmp(&b);
        }
        a_value.cmp(&b_value)
    });

    indices.into_iter().map(|index| indices[index]).collect()
}
